WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY carrier ORDER BY shipped_date, id) AS dedup_rank FROM shipments QUALIFY dedup_rank = 1), with_dims AS (SELECT s.*, p.discount FROM latest s LEFT JOIN orders p ON s.order_id = p.id WHERE p.shipping_fee BETWEEN 25 AND 37), enriched AS (SELECT src.id, src.order_id, src.carrier, src.shipped_date, src.cost, src.status, src.dedup_rank, b.amount, b.order_date, b.shipping_fee FROM with_dims src LEFT JOIN orders b ON src.order_id <=> b.id), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status, carrier ORDER BY shipped_date DESC, id) AS rn FROM enriched QUALIFY rn = 1), with_windows AS (SELECT *, NTILE(10) OVER (ORDER BY shipping_fee, id) AS shipping_fee_bucket, FIRST_VALUE(amount, TRUE) OVER (PARTITION BY MONTH(order_date), status ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_amount, NTILE(5) OVER (PARTITION BY status ORDER BY cost DESC, id) AS cost_bucket, SUM(amount) OVER (PARTITION BY order_id, carrier ORDER BY shipping_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount FROM ranked), scored AS (SELECT id, status, dedup_rank, amount, shipping_fee, rn, shipping_fee_bucket, first_known_amount, AVG(shipping_fee_bucket) OVER w_grp AS shipping_fee_bucket_avg_5_prior, AVG(cost) OVER (PARTITION BY DATE_TRUNC('MONTH', order_date) ORDER BY running_amount, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS cost_avg_5_prior, ROW_NUMBER() OVER (PARTITION BY carrier ORDER BY shipping_fee DESC, id) AS seq_no, ROUND(cost_bucket / SUM(cost_bucket) OVER (PARTITION BY YEAR(order_date)), 4) AS cost_bucket_share, SUM(shipping_fee_bucket) OVER (ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_shipping_fee_bucket FROM with_windows WINDOW w_grp AS (PARTITION BY order_id, status ORDER BY shipped_date, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING)) SELECT id, status, dedup_rank, amount, shipping_fee, rn, first_known_amount, cost_avg_5_prior, seq_no FROM scored;
